-- Disposable fictional database only; rolls back every identity and decision.
begin;
create function pg_temp.enrollment_ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end$$;
create function pg_temp.enrollment_denied(statement text,code text,label text) returns void language plpgsql as $$declare actual text;begin begin execute statement;exception when others then get stacked diagnostics actual=returned_sqlstate;end;if actual is distinct from code then raise exception 'FAIL: %, expected %, got %',label,code,actual;end if;raise notice 'PASS: %',label;end$$;
insert into auth.users(id,email,email_confirmed_at) select ('dddddddd-dddd-4ddd-8ddd-'||lpad(n::text,12,'0'))::uuid,'signup-'||n||'@example.invalid',case when n=2 then null else now() end from generate_series(1,7)n;
insert into auth.sessions(id,user_id) select ('eeeeeeee-eeee-4eee-8eee-'||lpad(n::text,12,'0'))::uuid,('dddddddd-dddd-4ddd-8ddd-'||lpad(n::text,12,'0'))::uuid from generate_series(1,7)n;
create function pg_temp.enrollment_login(n integer) returns void language plpgsql as $$begin perform set_config('request.jwt.claim.sub','dddddddd-dddd-4ddd-8ddd-'||lpad(n::text,12,'0'),true);perform set_config('request.jwt.claims',jsonb_build_object('session_id','eeeeeeee-eeee-4eee-8eee-'||lpad(n::text,12,'0'),'user_metadata',jsonb_build_object('role','pastoral_staff','status','active'))::text,true);end$$;
set local role anon;
select pg_temp.enrollment_denied($q$select public.complete_self_service_enrollment('Jamie Example')$q$,'42501','anonymous cannot create enrollment');
reset role;select pg_temp.enrollment_login(1);set local role authenticated;
select pg_temp.enrollment_denied($q$select public.self_service_signup_enabled()$q$,'42501','browser cannot read signup operator switch');
select pg_temp.enrollment_denied($q$select public.complete_self_service_enrollment('Jamie Example')$q$,'42501','database signup defaults disabled');
reset role;update app_private.enrollment_settings set enabled=true,allowed_email_domains=array['example.invalid'];
update auth.users set email='out-of-scope@example.com' where id='dddddddd-dddd-4ddd-8ddd-000000000003';select pg_temp.enrollment_login(3);set local role authenticated;
select pg_temp.enrollment_denied($q$select public.complete_self_service_enrollment('Outside Test Scope')$q$,'42501','direct RPC cannot bypass the isolated enrollment allowlist');
reset role;update auth.users set email='signup-3@example.invalid' where id='dddddddd-dddd-4ddd-8ddd-000000000003';
select pg_temp.enrollment_login(2);set local role authenticated;
select pg_temp.enrollment_denied($q$select public.complete_self_service_enrollment('Unconfirmed Example')$q$,'42501','unconfirmed email cannot create profile');
reset role;select pg_temp.enrollment_login(1);set local role authenticated;
select pg_temp.enrollment_denied($q$select public.complete_self_service_enrollment('x')$q$,'22023','invalid display name rejected in database');
select public.complete_self_service_enrollment('Jamie Example');
select public.complete_self_service_enrollment('Different Name Retry');
select pg_temp.enrollment_ok(public.my_membership_id() is not null,'confirmed signup can sign in while Unassigned');
select pg_temp.enrollment_ok(app_private.current_member_id() is null,'Unassigned account has no active-member authority');
select pg_temp.enrollment_ok((select count(id)=1 from public.members),'Unassigned direct RLS sees only own member name');
select pg_temp.enrollment_ok((select count(*)=0 from public.church_groups),'Unassigned cannot enumerate groups');
select pg_temp.enrollment_ok((select count(*)=0 from public.church_units),'Unassigned cannot enumerate units');
select pg_temp.enrollment_ok((select count(*)=0 from public.age_categories),'Unassigned cannot enumerate age categories');
select pg_temp.enrollment_ok((select count(*)=0 from public.departments),'Unassigned cannot enumerate departments');
select pg_temp.enrollment_ok((select count(*)=0 from public.member_placements),'signup creates no placement');
select pg_temp.enrollment_ok(public.member_workspace()->'self'->>'status'='intake','workspace reports intake status');
select pg_temp.enrollment_ok(public.member_workspace()->'self'->'groupId'='null'::jsonb,'group is null, never a synthetic Unassigned group');
select pg_temp.enrollment_ok(public.member_workspace()->'enrollment'->>'state'='unassigned','workspace has explicit Unassigned state');
select pg_temp.enrollment_ok(jsonb_array_length(public.member_workspace()->'directory')=0 and jsonb_array_length(public.member_workspace()->'groups')=0 and jsonb_array_length(public.member_workspace()->'unassignedMembers')=0,'workspace cannot enumerate other members or queue');
select pg_temp.enrollment_ok(public.member_workspace()->'contacts'->>'email'='signup-1@example.invalid','Unassigned sees own verified contact only');
select pg_temp.enrollment_denied($q$select * from app_private.self_service_enrollments$q$,'42501','private enrollment table not exposed');
select pg_temp.enrollment_denied($q$select public.member_command('organization.create','{"kind":"category","name":"Forged","reason":"Forged metadata attack"}',gen_random_uuid())$q$,'42501','forged metadata cannot authorize any member command');
select pg_temp.enrollment_denied($q$select public.member_module_home()$q$,'42501','Unassigned cannot read module feeds');
select pg_temp.enrollment_denied($q$select public.enrollment_command('enrollment.assign','{"memberId":"44444444-4444-4444-8444-000000000107","unitId":"33333333-3333-4333-8333-000000000001","verified":"yes","reason":"Self placement attack"}',gen_random_uuid())$q$,'42501','Unassigned cannot assign anyone');
reset role;
select pg_temp.enrollment_ok((select count(*)=1 from app_private.self_service_enrollments),'confirmation retries create exactly one enrollment');
select pg_temp.enrollment_ok((select count(*)=1 from app_private.audit_events where operation='enrollment.created'),'confirmation retries audit exactly once');
select pg_temp.enrollment_ok((select display_name='Jamie Example' from public.members where id=(select member_id from app_private.self_service_enrollments)),'retry cannot rename the membership record');
insert into app_private.member_private_contacts(member_id,email) values('44444444-4444-4444-8444-000000000109','signup-3@example.invalid');
select pg_temp.enrollment_login(3);set local role authenticated;
select pg_temp.enrollment_denied($q$select public.complete_self_service_enrollment('Existing Record')$q$,'42501','existing record email requires invitation verification');
reset role;
-- Seed operator and unit leader identities; real church data is never involved.
insert into app_private.account_links(member_id,auth_user_id,username) values('44444444-4444-4444-8444-000000000105','dddddddd-dddd-4ddd-8ddd-000000000004','signup_pastor'),('44444444-4444-4444-8444-000000000101','dddddddd-dddd-4ddd-8ddd-000000000005','signup_unit_leader'),('44444444-4444-4444-8444-000000000104','dddddddd-dddd-4ddd-8ddd-000000000007','signup_technical');
select pg_temp.enrollment_login(5);set local role authenticated;
select pg_temp.enrollment_ok(jsonb_array_length(public.member_workspace()->'unassignedMembers')=0,'unit leader cannot see global Unassigned queue');
select pg_temp.enrollment_denied($q$select public.enrollment_command('enrollment.assign','{"memberId":"cccccccc-cccc-4ccc-8ccc-000000000001","unitId":"33333333-3333-4333-8333-000000000001","verified":"yes","reason":"Out of scope assignment"}',gen_random_uuid())$q$,'42501','unit leader cannot claim an Unassigned member');
reset role;select pg_temp.enrollment_login(7);set local role authenticated;
select pg_temp.enrollment_ok(jsonb_array_length(public.member_workspace()->'unassignedMembers')=0,'technical role cannot see enrollment queue');
reset role;select pg_temp.enrollment_login(4);set local role authenticated;
select pg_temp.enrollment_ok(jsonb_array_length(public.member_workspace()->'unassignedMembers')=1,'pastoral authority sees pending Unassigned queue');
select pg_temp.enrollment_denied($q$select public.enrollment_command('enrollment.assign',jsonb_build_object('memberId',public.member_workspace()->'unassignedMembers'->0->>'id','unitId','33333333-3333-4333-8333-000000000001','verified','no','reason','Not verified assignment'),gen_random_uuid())$q$,'22023','assignment requires independent membership verification');
select pg_temp.enrollment_denied($q$select public.enrollment_command('enrollment.assign',jsonb_build_object('memberId',public.member_workspace()->'unassignedMembers'->0->>'id','unitId','33333333-3333-4333-8333-000000000001','verified','yes','role','pastoral_staff','reason','Forged role assignment'),gen_random_uuid())$q$,'22023','assignment rejects injected roles');
reset role;update public.church_units set is_active=false where id='33333333-3333-4333-8333-000000000003';set local role authenticated;
select pg_temp.enrollment_denied($q$select public.enrollment_command('enrollment.assign',jsonb_build_object('memberId',public.member_workspace()->'unassignedMembers'->0->>'id','unitId','33333333-3333-4333-8333-000000000003','verified','yes','reason','Archived unit assignment'),gen_random_uuid())$q$,'42501','cannot assign to an archived unit');
reset role;
create temporary table enrollment_test_context as select member_id as target,'ffffffff-ffff-4fff-8fff-000000000001'::uuid as request_id from app_private.self_service_enrollments;
grant select on enrollment_test_context to authenticated;
set local role authenticated;
select public.enrollment_command('enrollment.assign',(select jsonb_build_object('memberId',target::text,'unitId','33333333-3333-4333-8333-000000000001','verified','yes','reason','Independently verified fictional member') from enrollment_test_context),(select request_id from enrollment_test_context));
select public.enrollment_command('enrollment.assign',(select jsonb_build_object('memberId',target::text,'unitId','33333333-3333-4333-8333-000000000001','verified','yes','reason','Independently verified fictional member') from enrollment_test_context),(select request_id from enrollment_test_context));
select pg_temp.enrollment_denied($q$select public.enrollment_command('enrollment.reject',(select jsonb_build_object('memberId',target::text,'reason','Stale rejection attempt') from enrollment_test_context),gen_random_uuid())$q$,'22023','stale review cannot reject already placed member');
select pg_temp.enrollment_denied($q$select public.enrollment_command('enrollment.assign',(select jsonb_build_object('memberId',target::text,'unitId','33333333-3333-4333-8333-000000000002','verified','yes','reason','Changed retry payload') from enrollment_test_context),(select request_id from enrollment_test_context))$q$,'22023','retry request ID cannot change placement payload');
reset role;
select pg_temp.enrollment_ok((select count(*)=1 from public.member_placements where member_id=(select target from enrollment_test_context)),'initial placement retries create exactly one history row');
select pg_temp.enrollment_ok((select count(*)=1 from app_private.audit_events where operation='enrollment.assign'),'initial placement retries audit exactly once');
select pg_temp.enrollment_ok((select count(*)=0 from app_private.role_assignments where member_id=(select target from enrollment_test_context)),'assignment never grants a leadership role');
select pg_temp.enrollment_login(1);set local role authenticated;
select pg_temp.enrollment_ok(app_private.current_member_id() is not null,'assignment enables ordinary member authority');
select pg_temp.enrollment_ok(jsonb_array_length(public.member_workspace()->'enrollment'->'placementHistory')=1,'member sees own placement history');
select pg_temp.enrollment_ok(jsonb_array_length(public.member_workspace()->'unassignedMembers')=0,'assigned ordinary member still cannot see intake queue');
reset role;select pg_temp.enrollment_login(6);set local role authenticated;select public.complete_self_service_enrollment('Declined Example');reset role;
select pg_temp.enrollment_login(4);set local role authenticated;
select public.enrollment_command('enrollment.reject',jsonb_build_object('memberId',public.member_workspace()->'unassignedMembers'->0->>'id','reason','Independently verified duplicate profile'),gen_random_uuid());
reset role;select pg_temp.enrollment_login(6);set local role authenticated;
select pg_temp.enrollment_ok(public.my_membership_id() is null,'declined signup immediately loses own-record access');
select pg_temp.enrollment_denied($q$select public.complete_self_service_enrollment('Resurrection Attempt')$q$,'42501','declined account cannot enroll again');
reset role;select pg_temp.enrollment_login(1);delete from auth.sessions where id='eeeeeeee-eeee-4eee-8eee-000000000001';set local role authenticated;
select pg_temp.enrollment_ok(public.my_membership_id() is null,'revoked session immediately loses own-record access');
set constraints all immediate;
rollback;
